// 1. Pipeline Flush (Handling Misprediction)
// Invalidates instructions upon detected control hazard

enum PipelineStage { IF, ID, EX };
Instruction IF_IR, ID_IR;
bool branch_taken = true;
bool prediction = false;

if (branch_taken != prediction) {
    // Flush the pipeline stages
    IF_IR = NOP;
    ID_IR = NOP;
    PC = Target_Address; // Redirect Program Counter
}


// 2. Static Branch Prediction (Assume Not Taken)

#define PREDICT_NOT_TAKEN 0

int branch_predictor_state = PREDICT_NOT_TAKEN;
bool actual_outcome = true; // Misprediction occurred

if (actual_outcome && branch_predictor_state == PREDICT_NOT_TAKEN) {
    // Misprediction penalty (latency cost)
    Stall_Cycles += 3;
    Pipeline.flush_stages();
    PC = Target_Address;
}

// 3. Delayed Branching (Compiler Technique)

// Code Structure: [Instruction 1, Branch, Delay Slot, Target]

INST branch_instruction;
INST delay_slot_inst;

// The instruction in the delay slot executes 
// before the branch result affects PC flow.
Execute(delay_slot_inst);

if (branch_instruction.condition_met) {
    PC = branch_instruction.target;
} else {
    PC += 2; // Skips both branch and delay slot
}
